import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // For output, using PrintWriter for efficiency
        PrintWriter out = new PrintWriter(System.out);
        String line;

        int t = 1; // Not used in logic, but kept for consistency
        List<int[]> perms = new ArrayList<>();
        int[] permArray = {1, 2, 3, 4, 5, 6};
        permPermutations(permArray, 0, perms);

        line = br.readLine();
        int n = Integer.parseInt(line.trim());

        int[] a = getNumbers(br);
        int[] b = getNumbers(br);

        int maxMatch = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        int maxScore = 0;

        for (int[] perm : perms) {
            int[] aCopy = a.clone();
            int[] bCopy = b.clone();
            int score = 0;

            for (int el : perm) {
                int t = 0;
                switch (el) {
                    case 1:
                        t = Math.min(aCopy[0], bCopy[0]);
                        aCopy[0] -= t;
                        bCopy[0] -= t;
                        score += t;
                        break;
                    case 2:
                        t = Math.min(aCopy[0], bCopy[2]);
                        aCopy[0] -= t;
                        bCopy[2] -= t;
                        score += t;
                        break;
                    case 3:
                        t = Math.min(aCopy[1], bCopy[1]);
                        aCopy[1] -= t;
                        bCopy[1] -= t;
                        score += t;
                        break;
                    case 4:
                        t = Math.min(aCopy[1], bCopy[0]);
                        aCopy[1] -= t;
                        bCopy[0] -= t;
                        score += t;
                        break;
                    case 5:
                        t = Math.min(aCopy[2], bCopy[2]);
                        aCopy[2] -= t;
                        bCopy[2] -= t;
                        score += t;
                        break;
                    case 6:
                        t = Math.min(aCopy[2], bCopy[1]);
                        aCopy[2] -= t;
                        bCopy[1] -= t;
                        score += t;
                        break;
                }
            }
            maxScore = Math.max(maxScore, score);
        }

        out.print((n - maxScore) + " " + maxMatch);
        out.flush();
    }

    static int[] getNumbers(BufferedReader br) throws IOException {
        String[] parts = br.readLine().trim().split("\\s+");
        int[] nums = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i]);
        }
        return nums;
    }

    static void permPermutations(int[] arr, int index, List<int[]> perms) {
        if (index == arr.length - 1) {
            perms.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, i, index);
            permPermutations(arr, index + 1, perms);
            swap(arr, i, index);
        }
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    // Optional: Implement factorial and fast_power if needed, but not used in main logic
    static long factorial(int n) {
        long res = 1;
        for (int i = 1; i <= n; i++) {
            res = (res * i) % MOD;
        }
        return res;
    }

    static long fastPower(long base, int exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }
}
